head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS90005.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SearchApprovFileDtl
 * 설명       : 결재파일 내역을 조회한다.
 ***********************************************/
scwin.fn_SearchApprovFileDtl = function() {
    //선택체크
    if (dts_List.getTotalRow() == 0) return;
    if (!$c.bns.fn_IsChecked(dts_List, '')) {
        $c.win.alert("대상을 선택하십시오.");
        return;
    }

    //조회설정
    var qryId = '';
    var dsNm = 'BNS_APPROV_FILE_WRT';
    var mktactCd = $c.stf.getObjectValue(txb_BndMktactTpCd);

    //파라미터설정
    var param = '';
    var applId = '';
    var stdCd = '';
    var strtDd = '';
    if (mktactCd != '320') {
        param += "&{P}V_BND_APPL_ID=" + scwin.fn_GetApplId();
        applId = scwin.fn_GetApplId();
    } else {
        param += "&{P}V_STD_CD=" + scwin.fn_GetApplIdPack().STD_ISUR_CD;
        param += "&{P}V_STRT_DD=" + scwin.fn_GetApplIdPack().STRT_DD;
        stdCd = scwin.fn_GetApplIdPack().STD_ISUR_CD;
        strtDd = scwin.fn_GetApplIdPack().STRT_DD;
    }

    //국채,지방채	
    if (mktactCd == '111' || mktactCd == '121' || mktactCd == '112' || mktactCd == '122') {
        qryId = 'lds.stf.bnsnew.select.listApprovFileDtl111121112122';
    }
    //WIT종목지정
    else if (mktactCd == '113') {
        qryId = 'lds.stf.bnsnew.select.listApprovFileDtl113';
    }
    //WIT종목정보확정
    else if (mktactCd == '330') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt330';
    }
    //특수채,회사채,외국채
    else if (mktactCd == '131' || mktactCd == '132' || mktactCd == '141' || mktactCd == '151') {
        qryId = 'lds.stf.bnsnew.select.listApprovFileDtl131132141151';
    }
    //상호 변경, 합병/회사분할, 종목분할
    else if (mktactCd == '201' || mktactCd == '202' || mktactCd == '203') {
        qryId = 'lds.stf.bnschg.select.listApprovFileDt201202203';
    }
    //BW행사(최초)
    else if (mktactCd == '205') {
        qryId = 'lds.stf.bnschg.select.listApprovFileDt205';
    }
    //월별 금액조정,  중도상환(부분/전액), 권리행사(일반사채)
    else if (mktactCd == '301' || mktactCd == '303' || mktactCd == '304' || mktactCd == '315') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt301303304315';
    }
    //일별 금액조정
    else if (mktactCd == '320') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt320';
    }

    //권리행사(주식관련사채권)
    else if (mktactCd == '302') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt302';
    }
    //추가상장
    else if (mktactCd == '305') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt305';
    }
    //권리행사가액 변경
    else if (mktactCd == '306') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt306';
    }
    //발행가액, 표면이자율 변경
    else if (mktactCd == '307' || mktactCd == '308') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt307308';
    }
    //FRN 변동금리, 상환일 변경 
    else if (mktactCd == '309' || mktactCd == '311') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt309311';
    }
    /**
     * 보증기관 변경 (폐지, ASIS 테이블 - TB_BB212, TOBE 테이블 - 無)
     * mktactCd == '312' || mktactCd == '318' || mktactCd == '319'
     */

    //신용평가등급 변경
    else if (mktactCd == '313') {
        return '신용평가기관 채권정기-수시 평정 내역';
    }
    //수동상장폐지
    else if (mktactCd == '314') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt314';
    }
    //기타 2023-07-04 추가.
    else if (mktactCd == '316') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt316';
    }
    //스트립
    else if (mktactCd == '401') {
        qryId = 'lds.stf.bnschg.select.listApprovFileDt401Prnp';
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_Prnp, dsNm, qryId, param);
        if (dts_Prnp.getTotalRow() == 0) {
            $c.win.alert('결재파일데이타가 없습니다.');
            return;
        }
        var url = "/bns/BnsApprovFileDownload.do?";
        url += "BND_MKTACT_TP_CD=" + mktactCd;
        url += "&BND_APPL_ID=" + scwin.fn_GetApplId();
        location.href = url;
        return;
    }
    //스트립추가재결합
    else if (mktactCd == '402') {
        //원금
        qryId = 'lds.stf.bnschg.select.listApprovFileDt402Prnp';
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_Prnp, dsNm, qryId, param);
        if (dts_Prnp.getTotalRow() == 0) {
            $c.win.alert('결재파일데이타가 없습니다.');
            return;
        }
        var url = "/bns/BnsApprovFileDownload.do?";
        url += "BND_MKTACT_TP_CD=" + mktactCd;
        url += "&BND_APPL_ID=" + scwin.fn_GetApplId();
        location.href = url;
        return;
    }

    //스트립이 아닐 경우 웹브라우에서 보일 수 있도록 자바를 통해 다운로드 되도록 호출.
    //문제 있을 시 주석처리.
    var url = "/bns/BnsApprovFileDownload.do?";
    url += "BND_MKTACT_TP_CD=" + mktactCd;
    url += "&BND_APPL_ID=" + applId;
    url += "&STD_CD=" + stdCd;
    url += "&STRT_DD=" + strtDd;
    url += "&QUERY_ID=" + qryId;
    location.href = url;
    return;

    //스트립이 아닐 경우 결재데이터 조회
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ExcelList, dsNm, qryId, param);
};



/********************************************** 
 * 함수명   : fn_GetApplId
 * 설명       : 결재파일내역 신청ID를 리턴한다.
 ***********************************************/
scwin.fn_GetApplId = function() {
    var chk = '';
    var applId = '';
    var returnVal = '';
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        applId = dts_List.getCellData(i, 'BND_APPL_ID');
        if (applId == '') continue;
        chk = dts_List.getCellData(i, "CHECKED");
        if (chk == "T" || chk == "1") {
            returnVal += "'" + applId + "',";
        }
    }
    return returnVal.substring(0, returnVal.length - 1);
};


/********************************************** 
 * 함수명   : fn_GetApplIdPack
 * 설명       : 일별금액조정 결재파일내역 표준코드, 적용일을 리턴한다.
 ***********************************************/
scwin.fn_GetApplIdPack = function() {
    var chk = '';
    var stdcd = '',
        strtdd = '';
    var returnValStdCd = '',
        returnValStrtDd = '';
    var objReturnVal = new Object();
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        chk = dts_List.getCellData(i, "CHECKED");
        if (chk == "T" || chk == "1") {
            stdcd = dts_List.getCellData(i, 'STD_ISUR_CD');
            strtdd = dts_List.getCellData(i, 'STRT_DD');
            returnValStdCd += "'" + stdcd + "',";
            returnValStrtDd += "'" + strtdd + "',";
        }
    }
    objReturnVal.STD_ISUR_CD = returnValStdCd.substring(0, returnValStdCd.length - 1);
    objReturnVal.STRT_DD = returnValStrtDd.substring(0, returnValStrtDd.length - 1);
    return objReturnVal;
};


/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 결재파일새성정보를 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    //setObjectValue(txb_BndMktactTpCd, '401');
    var param = '';
    param += "&{P}V_BND_MKTACT_TP_CD=" + $c.stf.getObjectValue(txb_BndMktactTpCd);
    var dsNm = 'BNS_APPROV_FILE_WRT';
    var qryId = 'lds.stf.bnscommon.select.listApprovFileWrt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_BndMktactTpCd, arrPar[0].BND_MKTACT_TP_CD);
    }
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(txb_BndMktactTpCd, false);
    $c.stf.showObj(grd_ExcelList, false);
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Top);
    //호출파라미터설정
    scwin.fn_SetParam();
    //목록조회
    scwin.fn_Search();

    //엑셀데이터셋 초기화
    dts_ExcelList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_APPROV_FILE_WRT";
    dts_ExcelList.Reset();
    if ($c.stf.getObjectValue(txb_BndMktactTpCd) == "320") {
        var ColID = new Object();
        ColID.BND_APPL_ID = grd_List.getColumnID(2);
        $c.cm.setColumnProp(grd_List, ColID.BND_APPL_ID, "Show", false);
        $c.cm.setColumnProp(grd_List, "ISU_ISUR_NM", "Width", "290");
    }
    if ($c.stf.getObjectValue(txb_BndMktactTpCd) == "201" || $c.stf.getObjectValue(txb_BndMktactTpCd) == "202") {
        var ColID = new Object();
        ColID.STD_ISUR_CD = grd_List.getColumnID(3);
        ColID.ISU_ISUR_NM = grd_List.getColumnID(4);
        $c.cm.setColumnProp(grd_List, ColID.STD_ISUR_CD, "name", '발행기관코드');
        $c.cm.setColumnProp(grd_List, ColID.ISU_ISUR_NM, "name", '회사명');
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};
scwin.btn_ApprovFileCreat_onclick = function() {
    scwin.fn_SearchApprovFileDtl();
};
scwin.grd_List_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.bns.fn_SetAllCheckBox(grd_List, dts_List, bCheck);
};
scwin.dts_ExcelList_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        var fileContn = '';
        for (var i = 1; i <= dts_ExcelList.getTotalRow(); i++) {
            fileContn = dts_ExcelList.getCellData(i, 'APPROV_FILE_CONTN');
            if (fileContn == '') {
                $c.win.alert('[' + i + '행] 결제파일데이타가 없습니다.');
                return;
            }
        }
        var mktactCd = $c.stf.getObjectValue(txb_BndMktactTpCd);
        var title = dts_ExcelList.getCellData(1, 'TITLE');
        var fileNm = title;
        $c.cm.setColumnProp(grd_ExcelList, 'APPROV_FILE_CONTN', 'Name', title);
        grd_ExcelList.ExportFileEx($c.ut.cGetToday('yyyymmdd') + '_' + fileNm, true, 1, false);
    }
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
